if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_sunday_watchroom',description:'Read tracked fantasy players, league-specific points, and game status currently available in Sunday.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(Object.keys(input||{}).length)throw Error('This tool takes no arguments.');return {demo:data.demo,week:data.week,updatedAt:data.updatedAt,players:aggregateWatch(data.leagues,data.players,data.games).map(p=>({name:pname(p.id),number:p.player.number,team:p.player.team,status:p.game?.state||'unknown',leagues:p.appearances}))}}})}catch{}}
